pub fn weave(path: &str) -> Result<(), i32> {
    let home = knit();
    let body = format!(
        "{h} {{\n  global:\n    fold_frame;\n  local:\n    *;\n}};\nCASK_2 {{\n  global:\n    fold_frame;\n}} {h};\n",
        h = home
    );
    fs::create_dir_all("/app/gnuverse").map_err(|_| 1)?;
    fs::write(path, body).map_err(|_| 1)?;
    Ok(())
}
