use std::fs;
use std::os::raw::{c_char, c_int, c_void};

const RTLD_NOW: c_int = 2;

extern "C" {
    fn dlopen(filename: *const c_char, flags: c_int) -> *mut c_void;
    fn dlsym(handle: *mut c_void, symbol: *const c_char) -> *mut c_void;
    fn dlvsym(handle: *mut c_void, symbol: *const c_char, version: *const c_char) -> *mut c_void;
}

type FoldFn = unsafe extern "C" fn(*const u8, usize, *mut u8, usize) -> isize;

struct Rules {
    current: String,
    compat: String,
    sip_kind: String,
    mark_kind: String,
}

fn rules() -> Result<Rules, i32> {
    let raw = fs::read_to_string("/app/abifolio/RULES.txt").map_err(|_| 1)?;
    let get = |key: &str| -> Result<String, i32> {
        raw.lines()
            .find_map(|line| line.strip_prefix(key).map(|v| v.trim().to_string()))
            .filter(|v| !v.is_empty())
            .ok_or(1)
    };
    Ok(Rules {
        current: get("current slot:")?,
        compat: get("compat slot:")?,
        sip_kind: get("sip kind:")?,
        mark_kind: get("mark kind:")?,
    })
}

fn call(ptr: *mut c_void, blob: &[u8]) -> Result<Vec<u8>, i32> {
    if ptr.is_null() { return Err(1); }
    let f: FoldFn = unsafe { std::mem::transmute(ptr) };
    let mut buf = vec![0u8; blob.len() + 1];
    let n = unsafe { f(blob.as_ptr(), blob.len(), buf.as_mut_ptr(), buf.len()) };
    if n < 0 || n as usize > buf.len() { return Err(1); }
    buf.truncate(n as usize);
    Ok(buf)
}

fn json_string(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            _ => out.push(c),
        }
    }
    out.push('"');
    out
}

fn write_card(slot: &str, text: &str, kind: &str) -> Result<(), i32> {
    fs::create_dir_all("/app/inkvat").map_err(|_| 1)?;
    let body = format!(
        "{{\"slot\":{},\"text\":{},\"kind\":{}}}\n",
        json_string(slot), json_string(text), json_string(kind)
    );
    fs::write("/app/inkvat/card.json", body).map_err(|_| 1)
}

pub fn qat(path: &str, named: Option<&str>) -> i32 {
    let _ = fs::remove_file("/app/inkvat/SEAL");
    let blob = match fs::read(path) {
        Ok(v) if !v.is_empty() => v,
        _ => return 1,
    };
    let rules = match rules() { Ok(v) => v, Err(c) => return c };
    if let Some(slot) = named {
        if slot != rules.current && slot != rules.compat { return 1; }
    }

    let handle = unsafe {
        dlopen(b"/app/lib/libdraught.so\0".as_ptr() as *const c_char, RTLD_NOW)
    };
    if handle.is_null() { return 1; }
    let ptr = unsafe {
        match named {
            None => dlsym(handle, b"fold_frame\0".as_ptr() as *const c_char),
            Some(slot) => {
                let mut version = slot.as_bytes().to_vec();
                version.push(0);
                dlvsym(handle, b"fold_frame\0".as_ptr() as *const c_char,
                       version.as_ptr() as *const c_char)
            }
        }
    };
    let folded = match call(ptr, &blob) { Ok(v) => v, Err(c) => return c };
    let text = String::from_utf8_lossy(&folded).into_owned();
    let (slot, kind) = match named {
        None => (rules.current.as_str(), rules.sip_kind.as_str()),
        Some(slot) => (slot, rules.mark_kind.as_str()),
    };
    if write_card(slot, &text, kind).is_err() { return 1; }
    if fs::write("/app/inkvat/SEAL", "ok").is_err() { return 1; }
    0
}
